export const redirectUri=()=>location.origin+location.pathname;
export function beginAuth(clientId){if(!/^[a-zA-Z0-9]{10,100}$/.test(clientId))throw Error('Enter the Client ID from your Twitch application.');const state=crypto.randomUUID();sessionStorage.setItem('boss_oauth_state',state);sessionStorage.setItem('boss_client_id',clientId);location.assign('https://id.twitch.tv/oauth2/authorize?'+new URLSearchParams({client_id:clientId,redirect_uri:redirectUri(),response_type:'token',scope:'user:read:chat',state,force_verify:'true'}))}
export function consumeAuth(){const h=new URLSearchParams(location.hash.slice(1));if(!h.has('access_token')&&!h.has('error'))return null;history.replaceState(null,'',location.pathname+location.search);const expected=sessionStorage.getItem('boss_oauth_state');sessionStorage.removeItem('boss_oauth_state');if(!expected||h.get('state')!==expected)throw Error('Twitch sign-in state did not match. Please connect again.');if(h.has('error'))throw Error('Twitch authorization was cancelled. You can still use practice mode.');return {token:h.get('access_token'),clientId:sessionStorage.getItem('boss_client_id')}}
export class TwitchChat{
 constructor(onVote,onStatus){this.onVote=onVote;this.onStatus=onStatus;this.sockets=new Set();this.seen=new Set();this.stopped=false;this.attempt=0;this.timers=new Set()}
 async connect({token,clientId}){this.token=token;this.clientId=clientId;this.onStatus('connecting');const v=await this.validate();if(this.stopped)return;this.userId=v.user_id;this.login=v.login;this.open();this.validation=setInterval(()=>this.validate().catch(e=>this.fail(e.message)),3600000);this.expiration=setTimeout(()=>this.fail('Twitch session expired. Connect again.'),Math.max(0,(v.expires_in-30)*1000));}
 async validate(){const r=await fetch('https://id.twitch.tv/oauth2/validate',{headers:{Authorization:'OAuth '+this.token}});if(!r.ok)throw Error('Twitch session expired. Connect again.');const v=await r.json();if(v.client_id!==this.clientId||!v.scopes.includes('user:read:chat'))throw Error('Twitch authorization does not match this application. Connect again.');return v}
 open(url='wss://eventsub.wss.twitch.tv/ws',previous=null){if(this.stopped)return;const ws=new WebSocket(url);this.sockets.add(ws);let watchdog,keepalive=15000;const arm=()=>{clearTimeout(watchdog);watchdog=setTimeout(()=>ws.close(),keepalive+5000)};arm();
 ws.onmessage=async({data})=>{try{const m=JSON.parse(data),type=m.metadata.message_type;arm();if(type==='session_welcome'){if(this.stopped)return;keepalive=(m.payload.session.keepalive_timeout_seconds||10)*1000;arm();if(previous){previous.close();this.sockets.delete(previous)}else{const r=await fetch('https://api.twitch.tv/helix/eventsub/subscriptions',{method:'POST',headers:{Authorization:'Bearer '+this.token,'Client-Id':this.clientId,'Content-Type':'application/json'},body:JSON.stringify({type:'channel.chat.message',version:'1',condition:{broadcaster_user_id:this.userId,user_id:this.userId},transport:{method:'websocket',session_id:m.payload.session.id}})});if(!r.ok)throw Error('Could not subscribe to Twitch chat ('+r.status+'). Reconnect as the broadcaster.')}if(this.stopped)return;this.attempt=0;this.onStatus('connected',this.login)}
 if(type==='notification'&&m.metadata.subscription_type==='channel.chat.message'){const e=m.payload.event;const id=e.message_id||m.metadata.message_id;if(this.seen.has(id))return;this.seen.add(id);if(this.seen.size>2000)this.seen.delete(this.seen.values().next().value);this.onVote(e.chatter_user_id,e.chatter_user_name,e.message.text)}
 if(type==='session_reconnect'){const next=m.payload.session.reconnect_url;const parsed=new URL(next);if(parsed.protocol!=='wss:'||parsed.hostname!=='eventsub.wss.twitch.tv')throw Error('Twitch sent an invalid reconnect address.');this.open(next,ws)}
 if(type==='revocation')this.fail('Twitch chat access was revoked. Connect again.');}catch(e){this.fail(e.message)}};
 ws.onclose=()=>{clearTimeout(watchdog);this.sockets.delete(ws);if(this.stopped||this.sockets.size)return;this.onStatus('reconnecting',this.login);if(this.attempt>=5){this.fail('Twitch is unavailable. Connect again when ready.');return}const t=setTimeout(()=>{this.timers.delete(t);this.open()},Math.min(15000,1000*2**this.attempt++));this.timers.add(t)};ws.onerror=()=>{};
 }
 fail(message){this.stop();this.onStatus('error',message)}
 stop(){this.stopped=true;clearInterval(this.validation);clearTimeout(this.expiration);this.timers.forEach(clearTimeout);this.sockets.forEach(w=>w.close());this.sockets.clear();this.token=null}
}
